/**
 * Plays one recording (`design/components/audio-player.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/audio-player.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  claimSlot,
  clockTime,
  createCell,
  createDerived,
  elementRef,
  pauseOtherPlayers,
  scope,
  spokenDuration,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/audio-player.module.css'
import Button from '../controls/Button'
import Slider from '../controls/Slider'

export interface AudioPlayerMessages {
  /** The Button's name while the recording is not playing: "Play". */
  play: string
  /** The Button's name while it plays: "Pause". */
  pause: string
  /** The scrubber's name: "Playback position". */
  scrubber: string
  /** The scrubber's spoken value, from the elapsed and the total length. */
  position: (elapsed: string, total: string) => string
  /** Said in place of the scrubber when the file cannot be loaded. */
  failed: string
}

export interface AudioPlayerProps {
  /**
   * The recording's length in seconds, shown before the file gives its own. A file's finite
   * length replaces it. A file that gives none, as a recording a browser's `MediaRecorder`
   * wrote, keeps it.
   */
  duration?: number
  /**
   * Names the player, as a group: "Voice message from Ada".
   */
  label: string
  /**
   * The locale the clock and the spoken lengths are written in; the page's own when absent.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: AudioPlayerMessages
  /**
   * The recording played to its end.
   */
  onEnded?: () => void
  /**
   * The recording started playing, from a press on its Button.
   */
  onPlay?: () => void
  /**
   * The recording's URL. An empty string is the failed state: there is nothing to load.
   */
  src: string
}

/** Plays one recording. */
export default function AudioPlayer(given: AudioPlayerProps): JSX.Element {
  const props = mergeProps(
    {
      messages: (() => ({
        play: 'Play',
        pause: 'Pause',
        scrubber: 'Playback position',
        position: (elapsed: string, total: string) => `${elapsed} of ${total}`,
        failed: 'The recording could not be loaded',
      }))(),
    } as Defaults<AudioPlayerProps, 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const audio = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const playing = createCell(false)
    const finished = createCell(false)
    const elapsed = createCell(0)
    const fileLength = createCell(null as number | null)
    const failed = createCell(null as string | null)
    const scrub = createCell(null as number | null)
    const known = createDerived(
      () =>
        fileLength.value ??
        (props.duration !== undefined && Number.isFinite(props.duration) && props.duration > 0
          ? props.duration
          : null),
    )
    const total = createDerived(() => (known.value === null ? 0 : Math.floor(known.value)))
    const failing = createDerived(() => props.src === '' || failed.value === props.src)
    const seekable = createDerived(() => !failing.value && total.value >= 1)
    const position = createDerived(() =>
      finished.value ? total.value : Math.min(scrub.value ?? elapsed.value, total.value),
    )
    const status = createDerived(() =>
      failing.value ? 'failed' : playing.value ? 'playing' : finished.value ? 'ended' : undefined,
    )
    const failureId = createDerived(() => `${uid}-failure`)
    const spoken = createDerived(
      () =>
        (second: number): string =>
          known.value === null
            ? spokenDuration(second, props.locale)
            : props.messages.position(
                spokenDuration(second, props.locale),
                spokenDuration(total.value, props.locale),
              ),
    )
    const learn = createDerived(() => (): void => {
      const element = audio.value as HTMLAudioElement | null | undefined
      if (element == null) return
      const seconds = element.duration
      fileLength.value = Number.isFinite(seconds) && seconds > 0 ? seconds : null
    })
    const settle = createDerived(() => (): void => {
      playing.value = false
      finished.value = false
      elapsed.value = 0
      fileLength.value = null
      scrub.value = null
      if (failed.value !== props.src) failed.value = null
      const element = audio.value as HTMLAudioElement | null | undefined
      if (element == null) return
      if (element.error !== null) failed.value = props.src
      else if (element.readyState >= 1) learn.value()
    })
    const toggle = createDerived(() => (): void => {
      const element = audio.value as HTMLAudioElement | null | undefined
      if (element == null) return
      if (!element.paused) {
        element.pause()
        return
      }
      if (failing.value) {
        failed.value = null
        element.load()
      }
      element.play().catch(() => {})
    })
    const secondOf = createDerived(
      () =>
        (value: number | [number, number]): number =>
          typeof value === 'number' ? value : value[0],
    )
    const seek = createDerived(() => (second: number): void => {
      scrub.value = null
      elapsed.value = second
      finished.value = false
      const element = audio.value as HTMLAudioElement | null | undefined
      if (element != null) element.currentTime = second
    })
    const started = createDerived(() => (): void => {
      playing.value = true
      finished.value = false
      const element = audio.value as HTMLAudioElement | null | undefined
      if (element != null) pauseOtherPlayers(element)
      props.onPlay?.()
    })
    const stopped = createDerived(() => (): void => {
      playing.value = false
      finished.value = true
      props.onEnded?.()
    })
    const ticked = createDerived(() => (): void => {
      const element = audio.value as HTMLAudioElement | null | undefined
      if (element != null) elapsed.value = Math.floor(element.currentTime)
    })
    const effect1 = () => {
      settle.value()
    }
    watchEffect(
      createMemo(() => props.src),
      effect1,
      true,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'AudioPlayer',
        element: () => root.value,
        state: () => ({
          playing: playing.value,
          failed: failing.value,
          position: position.value,
          duration: total.value,
        }),
        actions: {},
        withholds: () => root.value,
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        class={styles.root}
        role="group"
        aria-label={props.label}
        data-state={status.value}
        data-member="audio-player"
        ref={root.attach}
      >
        {props.src !== '' ? (
          <audio
            preload="metadata"
            src={props.src}
            onloadedmetadata={() => learn.value()}
            ondurationchange={() => learn.value()}
            ontimeupdate={() => ticked.value()}
            onplay={() => started.value()}
            onpause={() => (playing.value = false)}
            onended={() => stopped.value()}
            onerror={() => ((failed.value = props.src), (playing.value = false))}
            ref={audio.attach}
          />
        ) : null}
        <Button
          variant="soft"
          tone="accent"
          iconOnly={true}
          icon={playing.value ? 'pause' : 'run'}
          label={playing.value ? props.messages.pause : props.messages.play}
          disabled={props.src === ''}
          aria-describedby={failing.value ? failureId.value : undefined}
          onClick={() => toggle.value()}
        />
        {failing.value ? (
          <span class={styles.failure} id={failureId.value} data-audio-player-part="failure">
            <span class={styles.failureGlyph} aria-hidden="true">
              <Icon name="error" size="sm" />
            </span>
            <span>{props.messages.failed}</span>
          </span>
        ) : (
          <>
            {/* scrubber */}
            <span class={styles.scrubber}>
              <Slider
                aria-label={props.messages.scrubber}
                min={0}
                max={seekable.value ? total.value : 1}
                step={1}
                value={seekable.value ? position.value : 0}
                disabled={!seekable.value}
                formatValue={spoken.value}
                onChange={(value: number | [number, number]) => {
                  scrub.value = secondOf.value(value)
                }}
                onCommit={(value: number | [number, number]) =>
                  seek.value(scrub.value ?? secondOf.value(value))
                }
              />
            </span>
            {/* time */}
            <span class={styles.time} data-audio-player-part="time" aria-hidden="true">
              <span>{clockTime(position.value, props.locale)}</span>
              {known.value !== null ? (
                <>
                  <span class={styles.divider}>{'/'}</span>
                  <span>{clockTime(total.value, props.locale)}</span>
                </>
              ) : null}
            </span>
          </>
        )}
      </div>
    )
  })
}
